class Solution:
    def coinChange(self, coins: List[int], amount: int) -> int:
        # Initialize a list to store the minimum number of coins needed for each amount
        dp = [float('inf')] * (amount + 1)
        dp[0] = 0  # Base case: 0 coins needed to make amount 0

        # Iterate over each coin
        for coin in coins:
            # Update the dp array for each amount from the coin value to the target amount
            for x in range(coin, amount + 1):
                dp[x] = min(dp[x], dp[x - coin] + 1)

        # If dp[amount] is still infinity, it means it's not possible to make the amount
        return dp[amount] if dp[amount] != float('inf') else -1

