class Solution:
    def snakesAndLadders(self, board: List[List[int]]) -> int:
        n = len(board)
        target = n * n
        queue = deque([1])
        visited = set([1])

        def get_next_square(curr):
            if curr >= target:
                return curr
            row, col = divmod(curr - 1, n)
            if row % 2 == 0:
                col = n - 1 - col
            else:
                col = col
            return board[row][col]

        steps = 0
        while queue:
            for _ in range(len(queue)):
                curr = queue.popleft()
                if curr == target:
                    return steps
                for next_square in range(curr + 1, min(curr + 7, target) + 1):
                    next_square = get_next_square(next_square)
                    if next_square not in visited:
                        visited.add(next_square)
                        queue.append(next_square)
            steps += 1

        return -1

