class Solution:
    def minCameraCover(self, root: Optional[TreeNode]) -> int:
        self.camera_count = 0

        def dfs(node: Optional[TreeNode]) -> int:
            if not node:
                return 2  # Null nodes are considered covered by their parent

            left = dfs(node.left)
            right = dfs(node.right)

            if left == 0 or right == 0:
                # If any child is not covered, place a camera here
                self.camera_count += 1
                return 1

            if left == 1 or right == 1:
                # If any child has a camera, this node is covered by its child
                return 2

            # If both children are covered by their children, this node is not covered
            return 0

        # If the root is not covered by any camera, we need to place a camera at the root
        if dfs(root) == 0:
            self.camera_count += 1

        return self.camera_count

