class Solution:
    def minimum_travel_time(self, n: int, m: int, a: int, b: int, roads: List[Tuple[int, int, int]]) -> List[int]:
        def find(parent, i):
            if parent[i] == i:
                return i
            parent[i] = find(parent, parent[i])
            return parent[i]

        def union(parent, rank, x, y):
            rootX = find(parent, x)
            rootY = find(parent, y)
            if rootX != rootY:
                if rank[rootX] > rank[rootY]:
                    parent[rootY] = rootX
                elif rank[rootX] < rank[rootY]:
                    parent[rootX] = rootY
                else:
                    parent[rootY] = rootX
                    rank[rootX] += 1

        def kruskal(n, edges, start):
            parent = list(range(n + 1))
            rank = [0] * (n + 1)
            mst_weight = 0
            edges.sort(key=lambda x: x[2])
            for u, v, c in edges:
                if find(parent, u) != find(parent, v):
                    union(parent, rank, u, v)
                    mst_weight += c
                    if u == start or v == start:
                        break
            return mst_weight

        result = []
        for p in range(1, n + 1):
            edges = [(u, v, c) for u, v, c in roads if u != p and v != p]
            edges.sort(key=lambda x: x[2])
            mst_weight = kruskal(n, edges, p)
            result.append(mst_weight)

        return result

