class Solution:
    def min_inversions(self, n: int, seq: List[int]) -> int:
        def count_inversions(seq):
            inversions = 0
            for i in range(n):
                for j in range(i + 1, n):
                    if seq[i] > seq[j]:
                        inversions += 1
            return inversions

        def min_flips_to_minimize_inversions(seq):
            flips = 0
            for i in range(n):
                if seq[i] > 0:
                    continue
                for j in range(i + 1, n):
                    if seq[j] < 0:
                        continue
                    flips += 1
                    seq[j] = -seq[j]
            return flips

        inversions = count_inversions(seq)
        flips = min_flips_to_minimize_inversions(seq)
        return inversions - flips

