class Solution:
    def count_segments(self, n: int, x: int, arr: List[int]) -> List[int]:
        # Initialize a list to store the count of segments for each value
        segment_count = [0] * (max(arr) + 1)

        # Iterate through the array
        for i in range(n):
            # Check if the current element can be the start of a segment of length x
            if i + x - 1 < n:
                # Count the segments starting from the current element
                segment_count[arr[i]] += 1

